import sqlite3
def connect(path):
    db=sqlite3.connect(path)
    db.execute('PRAGMA foreign_keys=ON')
    db.executescript('CREATE TABLE IF NOT EXISTS jobs(tenant TEXT, request_key TEXT, payload TEXT, status TEXT, attempts INTEGER, error TEXT, PRIMARY KEY(tenant, request_key)); CREATE TABLE IF NOT EXISTS totals(tenant TEXT PRIMARY KEY, amount INTEGER NOT NULL);')
    return db
def snapshot(db,tenant,key):
    row=db.execute('SELECT payload,status,attempts,error FROM jobs WHERE tenant=? AND request_key=?',(tenant,key)).fetchone()
    if row is None: return None
    return dict(zip(('payload','status','attempts','error'),row))

