import csv,io
def parse(text):
    reader=csv.DictReader(io.StringIO(text.replace(',', '|')),delimiter='|')
    if reader.fieldnames!=['tenant','name','count']: raise ValueError('header')
    for row in reader:
        if None in row or any(value is None for value in row.values()): raise ValueError('columns')
        yield row

